package com.mcnex.conversation;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
public final class KakaoQuestionProbe extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String message){if(!ok)throw new IllegalStateException(message);}
 private View find(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View match=find(g.getChildAt(i),text);if(match!=null)return match;}}return null;}
 private EditText edit(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=edit(g.getChildAt(i));if(e!=null)return e;}}return null;}
 public void onStart(){Bundle report=new Bundle();KakaoMemory store=null;Dialog[] dialog={null};File folder=new File(getTargetContext().getCacheDir(),"kakao-question-fixture");try{folder.mkdirs();Context isolated=new ContextWrapper(getTargetContext()){@Override public File getFilesDir(){return folder;}@Override public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences("qa-probe-"+name,mode);}};store=new KakaoMemory(isolated);store.clear();store.enabled(true);long now=System.currentTimeMillis(),yesterday=java.time.LocalDate.now().minusDays(1).atTime(12,0).atZone(java.time.ZoneId.systemDefault()).toInstant().toEpochMilli();store.add("today",now,"광학시험방","김시험","광학센서 검토 회의는 목요일 오후 2시입니다.");store.add("yesterday",yesterday,"전날시험방","박시험","자료를 전달했습니다.");check(store.find("광학센서 회의 일정").size()==1,"topic search");check(store.find("김시험 내용 알려줘").size()==1,"sender search");check(store.find("전날시험방 내용").size()==1,"room search");check(store.find("오늘 요약해줘").size()==1,"today scope");check(store.find("어제 요약해줘").size()==1,"yesterday scope");check(store.find("해왕성").isEmpty(),"unmatched question");MeetingManager manager=MeetingManager.get(getTargetContext());check(MeetingManager.AI_LOCK.tryLock(),"AI busy");try{KakaoAnswer.Answer answer=KakaoAnswer.generate(manager.engine(),"광학센서 회의는 언제인가요?",store.find("광학센서 회의"));check(!answer.references.isEmpty()&&answer.text.contains("목요일"),"selected model did not return grounded answer");report.putString("syntheticAiAnswer",answer.text);report.putString("model",manager.modelName());}finally{MeetingManager.AI_LOCK.unlock();}MainActivity activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));KakaoMemory memory=store;runOnMainSync(()->{activity.settings();check(find(activity.findViewById(android.R.id.content),"AI 기억 열기")!=null,"separate card");dialog[0]=activity.kakaoQuestion(memory);View page=dialog[0].getWindow().getDecorView();check(find(page,"질문하기")!=null,"question button");edit(page).setText("해왕성");find(page,"질문하기").performClick();});Thread.sleep(1200);runOnMainSync(()->{View page=dialog[0].getWindow().getDecorView();check(find(page,"저장된 알림에서 관련 내용을 찾지 못했습니다. 사람·대화방·주제 이름으로 다시 질문해 주세요.")!=null,"no-evidence UI");dialog[0].dismiss();});report.putString("result","search, sender, room, date scope, actual local AI, separate card and no-evidence UI passed");report.putBoolean("ok",true);}catch(Throwable e){report.putString("error",e.toString());report.putBoolean("ok",false);}finally{if(dialog[0]!=null)runOnMainSync(()->dialog[0].dismiss());if(store!=null){store.enabled(false);store.clear();store.close();}File ai=new File(folder,"AI");File[] files=ai.listFiles();if(files!=null)for(File file:files)file.delete();ai.delete();folder.delete();}finish(report.getBoolean("ok")?-1:0,report);}
}
